{"content": "def evaluate(store, task, profile, compute):
    # Check owner mismatch first
    if task['owner'] != profile['owner']:
        raise PermissionError("Owner mismatch")

    # Check version match
    if task['version'] != profile['version']:
        return None

    # Create cache key including all required components
    key = (task['owner'], profile['version'], task['criteria_version'], task['job_text'])

    # Use the key to check/store result
    if key not in store:
        try:
            result = compute()
            store[key] = result
        except Exception:
            # Exceptions from compute should propagate and not be cached
            raise
    return store[key]"}
